#[derive(Debug, Clone, Copy, PartialEq)]
struct Rectangle {
    x: f64,
    y: f64,
    width: f64,
    height: f64,
}

impl Rectangle {
    fn new(x: f64, y: f64, width: f64, height: f64) -> Option<Rectangle> {
        if width <= 0.0 || height <= 0.0 {
            return None;
        }
        Some(Rectangle { x, y, width, height })
    }

    fn square(x: f64, y: f64, side: f64) -> Option<Rectangle> {
        Rectangle::new(x, y, side, side)
    }

    fn area(&self) -> f64 {
        self.width * self.height
    }

    fn perimeter(&self) -> f64 {
        2.0 * (self.width + self.height)
    }

    fn is_square(&self) -> bool {
        self.width == self.height
    }

    fn contains_point(&self, px: f64, py: f64) -> bool {
        px >= self.x && px <= self.x + self.width && py >= self.y && py <= self.y + self.height
    }

    fn overlaps(&self, other: &Rectangle) -> bool {
        self.x < other.x + other.width
            && other.x < self.x + self.width
            && self.y < other.y + other.height
            && other.y < self.y + self.height
    }

    fn scale(&mut self, factor: f64) {
        self.width *= factor;
        self.height *= factor;
    }

    fn into_square(self) -> Rectangle {
        let side = if self.width < self.height { self.width } else { self.height };
        Rectangle { width: side, height: side, ..self }
    }
}

unitTests:
test("creating", || {
    let r = Rectangle::new(1.0, 2.0, 3.0, 4.0).unwrap();
    check_eq(r, Rectangle { x: 1.0, y: 2.0, width: 3.0, height: 4.0 });
    check_eq(Rectangle::new(0.0, 0.0, 0.0, 4.0), None);
    check_eq(Rectangle::new(0.0, 0.0, 3.0, -1.0), None);
    check(Rectangle::square(0.0, 0.0, 2.0).unwrap().is_square());
});

test("measuring", || {
    let r = Rectangle::new(0.0, 0.0, 3.0, 4.0).unwrap();
    check_near(r.area(), 12.0, 1e-9);
    check_near(r.perimeter(), 14.0, 1e-9);
    check(!r.is_square());
});

test("points and overlaps", || {
    let r = Rectangle::new(0.0, 0.0, 10.0, 5.0).unwrap();
    check(r.contains_point(10.0, 5.0));
    check(!r.contains_point(10.1, 2.0));
    let touching = Rectangle::new(10.0, 0.0, 2.0, 2.0).unwrap();
    let crossing = Rectangle::new(9.0, 4.0, 2.0, 2.0).unwrap();
    check(!r.overlaps(&touching));
    check(r.overlaps(&crossing) && crossing.overlaps(&r));
});

test("changing and converting", || {
    let mut r = Rectangle::new(1.0, 1.0, 2.0, 3.0).unwrap();
    r.scale(2.0);
    check_eq((r.x, r.y, r.width, r.height), (1.0, 1.0, 4.0, 6.0));
    let sq = r.into_square();
    check_eq(sq, Rectangle { x: 1.0, y: 1.0, width: 4.0, height: 4.0 });
    check_eq(r.width, 4.0);
});

